from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] != bg:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append(comp)
    template = max(comps, key=len)
    r0, r1 = min(r for r,c in template), max(r for r,c in template)
    c0, c1 = min(c for r,c in template), max(c for r,c in template)
    ar, ac = (r0+r1)//2, (c0+c1)//2
    shape = [(r-ar, c-ac, grid[r][c]) for r,c in template]
    out = [row[:] for row in grid]
    for comp in comps:
        if comp is template or len(comp) != 1:
            continue
        tr, tc = comp[0]
        for dr, dc, value in shape:
            rr, cc = tr+dr, tc+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
